referenceSolutions.python:
def duplicateCarriageFirstQualifyingSlip(readings, k):
    a=readings
    out=[]
    write=0
    for read in range(len(a)):
        if write==0 or a[read]!=a[write-1]:
            a[write]=a[read]
            write+=1
    out=a[:write]
    return next((x for x in out if x>=k),-1)

